<script setup>
import { reactive, ref, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MTag from '../../../components/mds/MTag.vue';
const props = defineProps({ tab:{type:String,default:'runs'}, runs:{type:Array,default:()=>[]}, competitors:{type:Array,default:()=>[]}, campaigns:{type:Array,default:()=>[]}, settings:{type:Object,default:()=>({})}, canManage:{type:Boolean}, saving:{type:Boolean}, error:{type:String,default:''}, selectedCampaign:{type:Object,default:null}, campaignResult:{type:Object,default:null}, evaluating:{type:Boolean} });
const emit=defineEmits(['back','tab','run-scan','create-competitor','edit-competitor','delete-competitor','save-competitor','create-campaign','edit-campaign','delete-campaign','save-campaign','select-campaign','evaluate-campaign','save-settings']);
const competitorForm=ref(null); const campaignForm=ref(null); const settingsDraft=reactive({ autoscan:props.settings.autoscan===true, intervalHours:props.settings.intervalHours||4, scanDays:props.settings.scanDays||30 });
watch(() => props.settings, (value) => { settingsDraft.autoscan=value?.autoscan===true; settingsDraft.intervalHours=value?.intervalHours||4; settingsDraft.scanDays=value?.scanDays||30; }, { deep:true });
function editCompetitor(record=null){competitorForm.value=record?{...record,channels:record.channels.join(', ')}:{name:'',website:'',fanpage:'',channels:'',note:''};}
function editCampaign(record=null){campaignForm.value=record?{...record,keywords:record.keywords.join(', '),competitors:record.competitors.join(', ')}:{name:'',startDate:'',endDate:'',message:'',content:'',audience:'',status:'draft',note:'',keywords:'',competitors:''};}
function submitCompetitor(){if(!competitorForm.value?.name?.trim())return;emit('save-competitor',competitorForm.value);competitorForm.value=null;}
function submitCampaign(){if(!campaignForm.value?.name?.trim())return;emit('save-campaign',campaignForm.value);campaignForm.value=null;}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="flex flex-wrap items-start justify-between gap-3 rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div><h1 class="text-[20px] font-semibold">Vận hành giám sát</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Theo dõi lượt quét và cấu hình nghiệp vụ. Các thao tác chạy qua API được bảo vệ phía máy chủ.</p></div><MButton variant="neutral" @click="emit('back')">Tổng quan</MButton></header><nav class="flex flex-wrap gap-2" aria-label="Các mục vận hành"><MButton v-for="item in [['runs','Lịch sử quét'],['competitors','Đối thủ'],['campaigns','Chiến dịch'],['settings','Thiết lập']]" :key="item[0]" :variant="tab===item[0]?'primary':'neutral'" @click="emit('tab',item[0])">{{item[1]}}</MButton></nav><p v-if="error" class="rounded-lg bg-[var(--mds-danger-bg)] px-4 py-3 text-[13px] text-[var(--mds-danger)]" role="alert">{{error}}</p>
<section v-if="tab==='runs'" class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="flex items-center justify-between border-b border-[var(--mds-border-light)] px-5 py-4"><h2 class="text-[15px] font-semibold">50 lượt quét gần nhất</h2><MButton v-if="canManage" variant="primary" :loading="saving" @click="emit('run-scan')">Quét theo bộ đang bật</MButton></header><div v-if="runs.length" class="overflow-x-auto"><table class="w-full min-w-[860px] text-left text-[13px]"><thead class="bg-[var(--mds-bg-page)] text-[12px] text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Bắt đầu</th><th class="px-3 py-3">Trạng thái</th><th class="px-3 py-3">Bộ từ khóa</th><th class="px-3 py-3">Đã lấy</th><th class="px-3 py-3">Tin mới</th><th class="px-3 py-3">Đã chấm</th><th class="px-5 py-3">Nguồn chạy</th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="run in runs" :key="run.id"><td class="px-5 py-3">{{run.startedAt||'—'}}</td><td class="px-3 py-3"><MTag :color="run.status==='done'?'success':run.status==='error'?'danger':'warning'">{{run.status||'—'}}</MTag><p v-if="run.error" class="mt-1 max-w-[260px] text-[12px] text-[var(--mds-danger)]">{{run.error}}</p></td><td class="px-3 py-3">{{run.queries}}</td><td class="px-3 py-3">{{run.fetched}}</td><td class="px-3 py-3">{{run.newMentions}}</td><td class="px-3 py-3">{{run.analyzed}}</td><td class="px-5 py-3">{{run.triggeredBy||'system'}}</td></tr></tbody></table></div><MEmptyState v-else title="Chưa có lượt quét" description="Lịch sử sẽ xuất hiện sau khi một lượt quét hoàn tất."/></section>
<section v-else-if="tab==='competitors'" class="rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]"><header class="flex items-center justify-between gap-3"><div><h2 class="text-[15px] font-semibold">Đối thủ cạnh tranh</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Danh sách dùng cho theo dõi và tổng hợp; AI không tự ghi dữ liệu.</p></div><MButton v-if="canManage" variant="primary" @click="editCompetitor()">Thêm đối thủ</MButton></header><div v-if="competitors.length" class="mt-4 grid gap-3 md:grid-cols-2"><article v-for="record in competitors" :key="record.id" class="rounded-lg bg-[var(--mds-bg-page)] p-4"><div class="flex items-start justify-between gap-2"><div><h3 class="font-medium">{{record.name}}</h3><p class="mt-1 text-[12px] text-[var(--mds-text-secondary)]">{{record.website||record.fanpage||'Chưa có kênh liên kết'}}</p></div><MTag color="neutral">{{record.channels.length}} kênh</MTag></div><p v-if="record.note" class="mt-3 text-[13px]">{{record.note}}</p><div v-if="canManage" class="mt-3 flex justify-end gap-2"><MButton variant="link" @click="editCompetitor(record)">Sửa</MButton><MButton variant="link" class="text-[var(--mds-danger)]" @click="emit('delete-competitor',record)">Xóa</MButton></div></article></div><MEmptyState v-else title="Chưa có đối thủ" description="Thêm đối thủ để so sánh trong báo cáo giám sát."/></section>
<section v-else-if="tab==='campaigns'" class="rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]"><header class="flex items-center justify-between gap-3"><div><h2 class="text-[15px] font-semibold">Chiến dịch truyền thông</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Từ khóa và thời gian do người dùng xác nhận trước khi phân tích.</p></div><MButton v-if="canManage" variant="primary" @click="editCampaign()">Thêm chiến dịch</MButton></header><div v-if="campaigns.length" class="mt-4 space-y-3"><article v-for="record in campaigns" :key="record.id" class="rounded-lg bg-[var(--mds-bg-page)] p-4"><div class="flex flex-wrap items-start justify-between gap-2"><div><h3 class="font-medium">{{record.name}}</h3><p class="mt-1 text-[12px] text-[var(--mds-text-secondary)]">{{record.startDate||'—'}} → {{record.endDate||'—'}} · {{record.status||'—'}}</p></div><div class="flex gap-2"><MButton variant="neutral" @click="emit('select-campaign',record)">Xem kết quả</MButton><MButton v-if="canManage" variant="link" @click="editCampaign(record)">Sửa</MButton><MButton v-if="canManage" variant="link" class="text-[var(--mds-danger)]" @click="emit('delete-campaign',record)">Xóa</MButton></div></div><p v-if="record.message" class="mt-2 text-[13px]">{{record.message}}</p></article></div><MEmptyState v-else title="Chưa có chiến dịch" description="Tạo chiến dịch để theo dõi hiệu quả theo thời gian."/><article v-if="selectedCampaign" class="mt-4 rounded-lg border border-[var(--mds-border)] p-4"><div class="flex items-center justify-between"><h3 class="font-semibold">Kết quả: {{selectedCampaign.name}}</h3><MButton variant="neutral" :loading="evaluating" @click="emit('evaluate-campaign',selectedCampaign)">AI đánh giá có kiểm soát</MButton></div><div v-if="campaignResult" class="mt-3 grid gap-3 sm:grid-cols-4"><div v-for="item in [['Tổng tin',campaignResult.total],['Tích cực',campaignResult.sentiment?.positive],['Trung tính',campaignResult.sentiment?.neutral],['Tiêu cực',campaignResult.sentiment?.negative]]" :key="item[0]" class="rounded-lg bg-[var(--mds-bg-page)] p-3"><strong class="text-[20px]">{{item[1]||0}}</strong><p class="text-[12px] text-[var(--mds-text-secondary)]">{{item[0]}}</p></div></div><p v-if="campaignResult?.evaluation" class="mt-3 whitespace-pre-line text-[13px]">{{campaignResult.evaluation}}</p></article></section>
<section v-else class="rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]"><h2 class="text-[15px] font-semibold">Thiết lập quét</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Tự động quét chỉ chạy ở máy chủ sau khi lưu.</p><div class="mt-4 grid max-w-[520px] gap-4 sm:grid-cols-2"><MSelect v-model="settingsDraft.autoscan" :options="[{value:true,label:'Bật tự động quét'},{value:false,label:'Tắt tự động quét'}]" placeholder="Chọn trạng thái"/><MInput v-model="settingsDraft.intervalHours" type="number" placeholder="Số giờ giữa các lượt"/><MInput v-model="settingsDraft.scanDays" type="number" placeholder="Số ngày lấy dữ liệu"/></div><div class="mt-5 flex justify-end"><MButton variant="primary" :loading="saving" @click="emit('save-settings',settingsDraft)">Lưu thiết lập</MButton></div></section>
<MDialog :model-value="Boolean(competitorForm)" :title="competitorForm?.id?'Sửa đối thủ':'Thêm đối thủ'" @update:model-value="!$event&&(competitorForm=null)" @confirm="emit('save-competitor',competitorForm);competitorForm=null"><div class="space-y-3"><MInput v-model="competitorForm.name" placeholder="Tên đối thủ"/><MInput v-model="competitorForm.website" placeholder="Website"/><MInput v-model="competitorForm.fanpage" placeholder="Fanpage"/><MInput v-model="competitorForm.channels" placeholder="Kênh, phân tách bằng dấu phẩy"/><MTextarea v-model="competitorForm.note" placeholder="Ghi chú"/></div></MDialog><MDialog :model-value="Boolean(campaignForm)" :title="campaignForm?.id?'Sửa chiến dịch':'Thêm chiến dịch'" @update:model-value="!$event&&(campaignForm=null)" @confirm="emit('save-campaign',campaignForm);campaignForm=null"><div class="space-y-3"><MInput v-model="campaignForm.name" placeholder="Tên chiến dịch"/><div class="grid gap-3 sm:grid-cols-2"><MInput v-model="campaignForm.startDate" type="date" placeholder="Từ ngày"/><MInput v-model="campaignForm.endDate" type="date" placeholder="Đến ngày"/></div><MInput v-model="campaignForm.message" placeholder="Thông điệp"/><MTextarea v-model="campaignForm.content" placeholder="Nội dung chính"/><MInput v-model="campaignForm.audience" placeholder="Đối tượng"/><MInput v-model="campaignForm.keywords" placeholder="Từ khóa, phân tách bằng dấu phẩy"/><MInput v-model="campaignForm.competitors" placeholder="Đối thủ, phân tách bằng dấu phẩy"/><MTextarea v-model="campaignForm.note" placeholder="Ghi chú"/></div></MDialog></div></section></template>
